const _ = require('lodash');
const { getValueString, indentString, serializeAnnotations, buildAnnotationsFromVariable, SECRET_PROVIDER_IDENTIFIER_FIELDS } = require('./utils');

const envToJson = (json) => {
  const variables = _.get(json, 'variables', []);
  const externalSecrets = _.get(json, 'externalSecrets', null);
  const color = _.get(json, 'color', null);

  const vars = variables
    .filter((variable) => !variable.secret)
    .map((variable) => {
      const { name, value, enabled } = variable;
      const prefix = enabled ? '' : '~';
      const annotationPrefix = serializeAnnotations(buildAnnotationsFromVariable(variable));

      return indentString(`${annotationPrefix}${prefix}${name}: ${getValueString(value)}`);
    });

  const secretVars = variables
    .filter((variable) => variable.secret)
    .map((variable) => {
      const { name, enabled } = variable;
      const prefix = enabled ? '' : '~';
      const annotationPrefix = serializeAnnotations(buildAnnotationsFromVariable(variable));
      return indentString(`${annotationPrefix}${prefix}${name}`);
    });

  let output = '';

  if (!variables || !variables.length) {
    output += `vars {
}
`;
  }

  if (vars.length) {
    output += `vars {
${vars.join('\n')}
}
`;
  }

  if (secretVars.length) {
    output += `vars:secret [
${secretVars.join(',\n')}
]
`;
  }

  const identifierField = externalSecrets && SECRET_PROVIDER_IDENTIFIER_FIELDS[externalSecrets.type];
  if (externalSecrets && identifierField && Array.isArray(externalSecrets.variables)) {
    const serializedVariables = externalSecrets.variables.map((variable) => {
      const { name, enabled, annotations } = variable;
      const prefix = enabled === false ? '~' : '';
      return indentString(`${serializeAnnotations(annotations)}${prefix}${name}: ${getValueString(variable[identifierField])}`);
    });

    const body = serializedVariables.length ? `\n${serializedVariables.join('\n')}\n` : '\n';
    output += `vars:externalsecrets:${externalSecrets.type} {${body}}
`;
  }

  if (color) {
    output += `color: ${color}
`;
  }

  return output;
};

module.exports = envToJson;
